cat > t.mjs <<'EOF'
import { reserve } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/baseline-d3-2/bot.mjs';
import { execFile } from 'node:child_process'; import { promisify } from 'node:util'; import fs from 'node:fs';
import assert from 'node:assert/strict';
const ex = promisify(execFile);
process.env.STATE_DIR = fs.mkdtempSync('/tmp/t8/s-') + '/nested';
const run = (u,n,iso)=>ex('node',['/tmp/t8/w.mjs',u,n,iso],{env:process.env}).then(r=>JSON.parse(r.stdout));
// 1: 8 procs x 10 concurrent calls, one user
const res = (await Promise.all(Array.from({length:8},()=>run('u1',10,'2026-10-23T03:00:00Z')))).flat();
assert.equal(res.filter(r=>r.allowed).length,2);
assert(res.filter(r=>!r.allowed).every(r=>r.rule==='daily-cap'));
assert(res.filter(r=>r.allowed).every(r=>r.rule===''));
// 2: restart persistence: new process, same Tokyo day (03:00Z=12:00 JST; 14:59Z=23:59 JST)
assert.equal((await run('u1',1,'2026-10-23T14:59:00Z'))[0].allowed,false);
// 3: Tokyo midnight = 15:00Z -> new day
assert.equal((await run('u1',1,'2026-10-23T15:00:00Z'))[0].allowed,true);
// 4: tz boundaries in-process, DST zone
const t=(u,iso,tz='America/New_York')=>reserve({userId:u,timeZone:tz,channel:'sms',now:new Date(iso)});
assert.equal((await t('ny','2026-11-01T03:59:00Z')).allowed,true);  // 23:59 EDT Oct 31
assert.equal((await t('ny','2026-11-01T04:00:00Z')).allowed,true);  // 00:00 EDT Nov 1 new day
assert.equal((await t('ny','2026-11-01T04:30:00Z')).allowed,true);
assert.equal((await t('ny','2026-11-01T10:00:00Z')).rule,'daily-cap'); // 05:00 EST still Nov 1 (25h day)
assert.equal((await t('ny','2026-11-02T04:59:00Z')).rule,'daily-cap'); // 23:59 EST Nov 1
assert.equal((await t('ny','2026-11-02T05:00:00Z')).allowed,true);
// 5: other user independent; invalid inputs
assert.equal((await t('other','2026-11-01T04:30:00Z')).allowed,true);
assert.equal((await t('x','2026-11-01T04:30:00Z','Nope/Zone')).rule,'invalid-request');
// 6: stale lock from crashed holder
const crypto=await import('node:crypto'); const h=crypto.createHash('sha256').update('stale').digest('hex');
fs.writeFileSync(`${process.env.STATE_DIR}/${h}.lock`,'999999:dead'); const old=new Date(Date.now()-60000); fs.utimesSync(`${process.env.STATE_DIR}/${h}.lock`,old,old);
assert.equal((await t('stale','2026-11-01T04:30:00Z')).allowed,true);
// 7: 200 users concurrently in one process, 5 calls each
const many = await Promise.all(Array.from({length:200*5},(_,i)=>t('m'+(i%200),'2026-11-01T12:00:00Z')));
assert.equal(many.filter(r=>r.allowed).length,400);
console.log('ALL OK', fs.readdirSync(process.env.STATE_DIR).filter(f=>f.endsWith('.lock')||f.endsWith('.tmp')).length,'leftover lock/tmp');
EOF
